(function(root){
const materialUnits=root.MaterialCore||(typeof require==='function'?require('./material-core.js'):null);
const finite=n=>typeof n==='number'&&Number.isFinite(n)&&n>=0;
const METRICS={area:{name:'Площадь обработки',unit:'м²'},faceArea:{name:'Площадь одной стороны',unit:'м²'},length:{name:'Длина материала',unit:'м'},mass:{name:'Масса',unit:'кг'},count:{name:'Количество',unit:'шт.'},volume:{name:'Объём материала',unit:'м³'}};
const unit=s=>({м2:'м²',м3:'м³'}[materialUnits.unitKey(s)]||materialUnits.unitKey(s));
const targetUnit=l=>!l.operation?l.unit:l.operation.mode==='machine'?'мин':l.operation.mode==='tariff'?({laser:'м',waterjet:'м',bending:'шт.',milling:'мин'}[l.operation.type]):'';
function validate(lines){const keys=new Set();for(const l of lines){if(l.processKey!==undefined){if(typeof l.processKey!=='string'||!/^[a-zA-Z0-9_-]{1,100}$/.test(l.processKey)||keys.has(l.processKey))throw Error('Некорректный или повторный ключ узла');keys.add(l.processKey);}if(l.processPosition!==undefined&&(!l.processPosition||!finite(l.processPosition.x)||!finite(l.processPosition.y)||l.processPosition.x>20000||l.processPosition.y>20000))throw Error('Некорректная позиция узла');if(l.processMetrics!==undefined){const m=l.processMetrics;if(l.kind!=='material'||!m||typeof m.unit!=='string'||typeof m.source!=='string'||Object.keys(METRICS).some(k=>m[k]!==undefined&&m[k]!==null&&!finite(m[k])))throw Error('Некорректные характеристики материала');}if(l.processBinding!==undefined){const b=l.processBinding;if(!b||!l.processKey||typeof b.from!=='string'||!/^[a-zA-Z0-9_-]{1,100}$/.test(b.from)||!Object.hasOwn(METRICS,b.metric)||!['direct','norm','context','geometry'].includes(b.mode)||!finite(b.factor)||b.factor<=0||typeof b.unit!=='string'||typeof b.note!=='string')throw Error('Некорректная связь процесса');}}
 for(const l of lines){const b=l.processBinding,o=l.processOutput;if(b?.mode==='geometry'&&(!['unit','batch','parts'].includes(b.geometryBasis)||b.amount!==null&&b.amount!==undefined&&!finite(b.amount)||b.parts!==null&&b.parts!==undefined&&!finite(b.parts)))throw Error('Некорректная геометрия работы');if(o&&(!['unit','batch'].includes(o.basis)||typeof o.source!=='string'||Object.keys(METRICS).some(k=>o[k]!==undefined&&o[k]!==null&&!finite(o[k]))))throw Error('Некорректные характеристики готовых деталей');}
 const byKey=new Map(lines.filter(l=>l.processKey).map(l=>[l.processKey,l])),done=new Set();for(const l of lines){const path=new Set();let cursor=l;while(cursor&&!done.has(cursor.processKey)){if(path.has(cursor.processKey))throw Error('Цикл связей процессов');path.add(cursor.processKey);cursor=cursor.processBinding?byKey.get(cursor.processBinding.from):null;}path.forEach(k=>done.add(k));}return true;}
function ownMetrics(l){const m=l.processMetrics,u=unit(l.unit);const values=Object.fromEntries(Object.keys(METRICS).map(k=>[k,null]));if(m&&unit(m.unit)!==u)return {values,error:'Единица материала изменилась: перепроверьте характеристики узла'};
 if(m)for(const k of Object.keys(METRICS))if(finite(m[k]))values[k]=m[k];
 if(u==='м²'){values.area=values.area??1;values.faceArea=values.faceArea??1;}if(u==='м³')values.volume=values.volume??1;if(u==='м')values.length=values.length??1;if(u==='кг')values.mass=values.mass??1;if(u==='шт'||u==='лист')values.count=values.count??1;if(values.mass===null&&finite(l.mass))values.mass=l.mass;
 return {values,error:''};}
function isCut(l){return l.kind==='work'&&(['laser','waterjet'].includes(l.operation?.type)||/^(раскрой|резка|распиловка|торцовка|лазерная резка|гидроабразивная резка)|на торцовочной/i.test(l.name));}
function physical(key,lines,q){const map=new Map(lines.filter(l=>l.processKey).map(l=>[l.processKey,l])),visited=new Set();let l=map.get(key);while(l){if(visited.has(l.processKey))return {error:'Цикл связей процессов'};visited.add(l.processKey);if(l.processOutput){const o=l.processOutput;if(!Number.isInteger(q)||q<1)return {error:'Заполните тираж'};return {values:Object.fromEntries(Object.keys(METRICS).map(k=>[k,finite(o[k])?o[k]*(o.basis==='batch'?1:q):null])),source:l,finished:true};}if(isCut(l))return {error:'После раскроя задайте характеристики готовых деталей; площадь заготовки не передаётся автоматически'};if(!l.processBinding)break;l=map.get(l.processBinding.from);}if(!l)return {error:'Исходный узел удалён или не найден'};if(l.kind!=='material')return {error:'У процесса нет связи с исходным материалом'};if(!finite(l.qty)||!Number.isInteger(q)||q<1)return {error:'Заполните количество исходного материала и тираж'};const {values,error}=ownMetrics(l);if(error)return {error};const quantity=l.qty*(l.scope==='batch'?1:q);return {values:Object.fromEntries(Object.entries(values).map(([k,v])=>[k,v===null?null:v*quantity])),source:l};}
function resolve(s,q=s.qty){if(!s.lines.some(l=>l.processBinding))return {state:s,errors:[]};const errors=[];try{validate(s.lines);}catch(e){errors.push(e.message);}const map=new Map(s.lines.map(l=>[l.processKey,l]));const lines=s.lines.map(l=>{if(!l.processBinding)return l;const b=l.processBinding,out={...l},expected=targetUnit(l);let value=null,error=map.has(b.from)?'':'Исходный узел удалён или не найден';
 if(b.mode==='context'){if(error)errors.push(l.name+': '+error);out.processSourceKey=b.from;delete out.processBinding;return out;}
 if(!error&&!expected)error='Ручная стоимость операции не поддерживает автообъём';if(!error&&l.pricingMode==='client')error='Автообъём недоступен для готовой клиентской цены';if(!error&&unit(b.unit)!==unit(expected))error='Единица процесса изменилась: перепроверьте связь';
 if(b.mode==='geometry'){if(!error&&(!finite(b.amount)||b.geometryBasis==='parts'&&!finite(b.parts)))error=isCut(l)?'Заполните длину реза и количество деталей':'Заполните геометрический объём работы';if(!error){const total=b.amount*(b.geometryBasis==='parts'?b.parts:1)*(b.geometryBasis==='batch'?1:q);value=total/(l.operation||l.scope!=='batch'?q:1);}}
 else {const p=physical(b.from,s.lines,q);if(!error)error=p.error;if(!error&&b.mode==='direct'&&(unit(METRICS[b.metric]?.unit)!==unit(expected)||b.factor!==1))error='Для разных единиц нужна явная норма пересчёта';if(!error&&(!finite(b.factor)||b.factor<=0))error='Укажите положительную норму';if(!error&&p.values[b.metric]===null)error='У источника неизвестна характеристика «'+METRICS[b.metric].name+'»';if(!error)value=p.values[b.metric]*b.factor/(l.operation||l.scope!=='batch'?q:1);}
 if(!error&&!finite(value))error='Некорректный результат пересчёта';if(error){value=null;errors.push(l.name+': '+error);}if(l.operation)out.operation={...l.operation,[l.operation.mode==='machine'?'minutes':'measure']:value};else out.qty=value;out.processSourceKey=b.from;delete out.processBinding;return out;});return {state:{...s,lines},errors:[...new Set(errors)]};}
function catalogMetrics(l,c){const own=ownMetrics(l).values,m={...own,unit:l.unit,source:'Единица материала и заданная масса'};if(c&&unit(c.unit)===unit(l.unit)){for(const [key,label] of [['area','Площадь ВСЕХ поверхностей, м2'],['faceArea','Площадь поверхности, м2'],['volume','Объем материала, м3']]){const v=c.details?.[label];if(m[key]===null&&finite(v)){m[key]=v;m.source=c.book+' · '+c.sheet+' · строка '+c.row+'; площади на одну '+l.unit;}}const length=c.details?.['Длина изделия, мм'];if(m.length===null&&finite(length)){m.length=length/1000;m.source+='; длина изделия из справочника, мм → м';}}return m;}
root.ProcessGraphCore={METRICS,unit,targetUnit,validate,isCut,ownMetrics,physical,resolve,catalogMetrics};if(typeof module!=='undefined')module.exports=root.ProcessGraphCore;
})(typeof window!=='undefined'?window:globalThis);
